def run_count(children, root, request_ids, lifo):
    pending, answers, nodes = [], [], {}
    for node_id, child_ids in children.items():
        def send(target, message, sender=node_id):
            if target is None:
                answers.append((message['request_id'], message['count']))
            else:
                pending.append((sender, target, dict(message)))
        nodes[node_id] = AsyncTreeCounter(node_id, child_ids, send)
    for request_id in request_ids:
        nodes[root].receive_message(None, {'type': 'count_request', 'request_id': request_id})
    while pending:
        sender, target, message = pending.pop(-1 if lifo else 0)
        nodes[target].receive_message(sender, message)
    return answers, nodes
answers, nodes = run_count({'8': ['11', '14'], '11': ['17', '19'], '14': ['23'], '17': [], '19': [], '23': []}, '8', ['request-a'], lifo=True)
assert answers == [('request-a', 6)]
assert all(not node.state for node in nodes.values())

pending, answers, nodes = [], [], {}
def send(target, message):
