assert nodes['root'].state == {}

pending, answers, nodes = [], [], {}
children = {'r': ['a', 'b'], 'a': [], 'b': []}
for node_id, child_ids in children.items():
    def send(target, message, sender=node_id):
        if target is None:
            answers.append((message['request_id'], message['count']))
        else:
            pending.append((sender, target, dict(message)))
    nodes[node_id] = AsyncTreeCounter(node_id, child_ids, send)
for request_id in ['first', 'second']:
    nodes['r'].receive_message(None, {'type': 'count_request', 'request_id': request_id})
while pending:
    sender, target, message = pending.pop()
    nodes[target].receive_message(sender, message)
assert sorted(answers) == [('first', 3), ('second', 3)]
assert all(not node.state for node in nodes.values())
